const crypto = require('crypto');
const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const given = headers['x-saathi-signature'] ?? headers['X-Saathi-Signature'] ?? '';
const secret = $env.SAATHI_N8N_SECRET ?? '';
const expected = secret ? `sha256=${crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex')}` : '';
const verified = Boolean(secret && given && given === expected);
const event = typeof body === 'object' && body !== null ? body : {};
const route = event.event === 'delivery.needs_review' ? 'operator_review' : event.event === 'report.generated' ? 'report_ready' : event.event === 'campaign.approved' || event.event === 'jobs.queued' ? 'campaign_monitoring' : 'audit';
return [{ json: { ok: verified, verified, route: verified ? route : 'reject', received_event: event.event ?? 'unknown', next_action: verified ? (route === 'operator_review' ? 'Ask a merchant operator to review the delivery state; do not retry blindly.' : route === 'report_ready' ? 'Share a descriptive report with synthetic-data caveats.' : route === 'campaign_monitoring' ? 'Watch the mock queue and keep approval as the human gate.' : 'Retain the event for audit.') : 'Reject the event and investigate the shared secret.', event } }];
